  const customer:AiCustomerDraftInput={companyNameEn:field('companyNameEn',160),companyNameAr:field('companyNameAr',160),contactPerson:field('contactPerson',120),addressEn:field('addressEn',220),addressAr:field('addressAr',220),city:field('city',100),country:field('country',100),phone:field('phone',80),email:field('email',160),vatTaxNumber:field('vatTaxNumber',100),commercialRegistration:field('commercialRegistration',100)};
