    const kind=value.kind==='invoice'?'invoice':value.kind==='proforma'?'proforma':null;if(!kind)return null;const defaultCurrency=bounded(context.drafting.defaults.currency,8).toUpperCase();const requestedCurrency=bounded(value.currency,8).toUpperCase();const currency=requestedCurrency&&(requestedCurrency===defaultCurrency||messageContainsText(message,requestedCurrency))?requestedCurrency:defaultCurrency;if(!/^[A-Z0-9]{2,8}$/.test(currency))return null;const customer=context.drafting.customers.find(row=>row.id===String(value.customerId||''));const customerId=customer&&messageContainsText(message,customer.name)?customer.id:'';const customerDraft=customerId?null:safeCustomerDraft(value.customerDraft??value.customer,message);const language:DocumentLanguage=value.language==='ar'||value.language==='bilingual'?value.language:'en';const items=Array.isArray(value.items)?value.items.slice(0,20).map((entry:any)=>safeDraftItem(entry,context,message,currency)).filter(Boolean) as AiDraftItemInput[]:[];if(!items.length)return null;return{capability:'document.createDraft',kind,customerId,customerDraft,currency,language,items,incoterm:groundedText(value.incoterm,message,context.drafting.defaults.incoterm,80),paymentTerms:groundedText(value.paymentTerms,message,context.drafting.defaults.paymentTerms,120),deliveryTime:groundedText(value.deliveryTime,message,context.drafting.defaults.deliveryTime,120),validity:groundedText(value.validity,message,context.drafting.defaults.validity,100),remarks:groundedText(value.remarks,message,'',500),notes:groundedText(value.notes,message,'',500),label:bounded(value.label||`Create ${kind} draft`,80),rationale:bounded(value.rationale,220)};
