function financeIntent(message:string):boolean{const value=normalized(message);return['sales','profit','collected','outstanding','overdue','receivable','customer balance','invoice total','revenue','compare','yesterday','today','month','مبيعات','ربح','محصل','المحصّل','مستحق','متأخر','فاتورة','اليوم','أمس','شهر','قارن'].some(token=>value.includes(token));}
