function documentReviewIntent(message:string):boolean{const value=normalized(message);return['review this document','review document','before finalizing','check this quote','check this invoice','راجع هذا المستند','راجع المستند','قبل الاعتماد','راجع عرض السعر','راجع الفاتورة'].some(token=>value.includes(token));}
function itemActionIntent(message:string):boolean{const value=normalized(message);return['archive','restore','duplicate','category','tag','metadata','أرشف','ارشفة','أرشفة','استعادة','مكرر','تصنيف','وسم'].some(token=>value.includes(token));}
function businessIntent(message:string):boolean{const value=normalized(message);return['product','item','supplier','purchase','landed','customer','payment behavior','risk','aging','منتج','صنف','مورد','شراء','عميل','سلوك الدفع','مخاطر','أعمار'].some(token=>value.includes(token));}
