function screenLabel(screen:AiWorkspaceScreen):string{switch(screen){case'home':return t('Home','الرئيسية');case'documents':return t('Documents','المستندات');case'customers':return t('Customers','العملاء');case'receivables':return t('Finance','المالية');case'reports':return t('Reports','التقارير');case'items':return t('Products & Inventory','المنتجات والمخزون');case'operations':return t('Purchasing','المشتريات');case'editor':return t('Document Editor','محرر المستند');}}
function starterPrompts(screen:AiWorkspaceScreen):string[]{if(screen==='home')return[t('Give me today’s business brief','أعطني ملخص الأعمال اليوم'),t('Create a quotation draft','أنشئ مسودة عرض سعر')];if(screen==='reports')return[t('Explain this month so far','اشرح أداء هذا الشهر حتى الآن'),t('Compare this month with last month','قارن هذا الشهر بالشهر الماضي')];if(screen==='receivables')return[t('Who needs collection follow-up first?','من يحتاج متابعة تحصيل أولًا؟'),t('Draft a collection message for an overdue customer','جهز رسالة تحصيل لعميل متأخر')];if(screen==='customers')return[t('Explain customer payment behavior','اشرح سلوك دفع العملاء'),t('Show customers with credit risk signals','اعرض العملاء مع مؤشرات مخاطر ائتمانية')];if(screen==='items')return[t('Analyze product pricing and margins','حلل تسعير وهوامش الأصناف'),t('Show duplicate, dormant or incomplete products','اعرض الأصناف المكررة أو الخاملة أو الناقصة')];if(screen==='operations')return[t('Compare supplier costs by product','قارن تكاليف الموردين حسب الصنف'),t('Show recent landed-cost increases','اعرض ارتفاعات تكلفة الوصول الأخيرة')];if(screen==='editor')return[t('Review this document before finalizing','راجع هذا المستند قبل الاعتماد'),t('Improve and translate the item descriptions','حسّن وترجم أوصاف الأصناف')];return[t('What can you help me with here?','كيف يمكنك مساعدتي هنا؟'),t('Show me where reports are','أرني أين توجد التقارير')];}

