export class AiCopilot extends React.Component<Props,State>{
  state:State={open:false,busy:false,input:'',error:'',messages:[],proposal:null,audit:[],auditOpen:false,review:null};
  private mounted=false;
  private pending=false;
  private applying=false;
  private previousFocus:HTMLElement|null=null;
  private overlayWasOpen=false;
  private panel=()=>document.getElementById('lourex-ai-panel');
  private containFocus=()=>{if(this.state.open)containOverlayFocus(this.panel());};
  private requestGeneration=0;
  private requestController:AbortController|null=null;
  private cancelRequest=()=>{(this as any).__lourexAttachmentAbort?.abort();this.requestGeneration+=1;this.requestController?.abort();this.requestController=null;this.pending=false;};
  private currentRequest=(generation:number,controller:AbortController)=>this.mounted&&generation===this.requestGeneration&&!controller.signal.aborted;
  componentDidMount():void{this.mounted=true;document.addEventListener('focusin',this.containFocus);document.addEventListener('keydown',this.onKeyDown);window.addEventListener(CONTEXTUAL_ADVISOR_EVENT,this.openContext);}
  componentDidUpdate(previous:Props):void{
    if(!this.overlayWasOpen&&this.state.open){
      this.overlayWasOpen=true;
      this.previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
      lockOverlayScroll(this);
      window.requestAnimationFrame(()=>{if(this.mounted&&this.state.open)containOverlayFocus(this.panel());});
    }else if(this.overlayWasOpen&&!this.state.open){this.overlayWasOpen=false;unlockOverlayScroll(this);restoreOverlayFocus(this.previousFocus);this.previousFocus=null;}
    if(previous.screen!==this.props.screen||previous.language!==this.props.language||previous.activeDocument?.id!==this.props.activeDocument?.id){this.cancelRequest();this.setState({busy:this.applying,proposal:null,review:null,error:''});}}
  componentWillUnmount():void{this.mounted=false;unlockOverlayScroll(this);document.removeEventListener('focusin',this.containFocus);this.cancelRequest();document.removeEventListener('keydown',this.onKeyDown);window.removeEventListener(CONTEXTUAL_ADVISOR_EVENT,this.openContext);}
  private openContext=(event:Event)=>{const detail=(event as CustomEvent).detail;if(!this.mounted||(topOverlay()&&topOverlay()!==this.panel())||this.pending||this.applying||this.state.busy||detail?.screen!==this.props.screen||typeof detail?.question!=='string')return;const input=bounded(detail.question,Math.min(MAX_MESSAGE_CHARS,1000));if(!input)return;this.setState({open:true,input,proposal:null,error:''},()=>document.querySelector<HTMLInputElement>('#lourex-ai-panel .lourex-ai-compose input')?.focus());};
  private onKeyDown=(event:KeyboardEvent)=>{
    const panel=this.panel();if(event.defaultPrevented||!this.state.open||!ownsOverlay(panel)||!panel)return;
    if(event.key==='Escape'){
      if(panel.querySelector('[role="menu"]:not([hidden])'))return;
      event.preventDefault();this.toggle();return;
    }
    trapOverlayTab(event,panel);
  };
  private addAudit=(capability:AiCapabilityId,outcome:AiAuditEntry['outcome'])=>this.setState(state=>({audit:[{id:id('audit'),at:new Date().toISOString(),capability,outcome,screen:this.props.screen},...state.audit].slice(0,30)}));
  private toggle=()=>{if(this.applying||(!this.state.open&&topOverlay()))return;if(this.state.open)this.cancelRequest();this.setState(state=>({open:!state.open,busy:false,error:'',proposal:state.open?null:state.proposal,review:state.open?null:state.review}));};
  private ask=async(raw?:string)=>{
    if(this.pending||this.applying||this.state.busy)return;const message=String(raw??this.state.input).trim().slice(0,MAX_MESSAGE_CHARS);if(!message)return;this.pending=true;const generation=++this.requestGeneration,controller=new AbortController();this.requestController=controller;const capability=capabilityFor(message,this.props.screen);const pendingDocumentProposal=this.state.proposal?.capability==='document.createDraft'||this.state.proposal?.capability==='document.updateDraft'?this.state.proposal:null;const pendingDocumentReview=pendingDocumentProposal?this.state.review:null;const userMessage:AiMessage={id:id('user'),role:'user',text:message};const memory=this.state.messages.slice(-4).map(entry=>`${entry.role==='user'?'User':'Advisor'}: ${entry.text}`).join('\n').slice(-520);this.setState(state=>({busy:true,error:'',input:'',proposal:null,review:null,messages:[...state.messages,userMessage]}));this.addAudit(capability,'requested');
    const calculation=advisorCalculation(message,this.props.language==='ar'?'ar':'en');if(calculation){const assistant:AiMessage={id:id('assistant'),role:'assistant',text:calculation.summary};this.setState(state=>({busy:false,proposal:pendingDocumentProposal,review:pendingDocumentReview,messages:[...state.messages,assistant]}));this.addAudit('finance.explain','answered');this.pending=false;this.requestController=null;return;}
    try{const resumed=await resumeVaultSession();if(!this.currentRequest(generation,controller))return;if(!resumed)throw new Error(t('Unlock LOUREX before using LOUREX Advisor.','افتح قفل LOUREX قبل استخدام مستشار LOUREX.'));const financeSource:AiFinanceSource={documents:resumed.vault.documents,payments:resumed.vault.payments,customers:resumed.vault.customers,activeDocument:this.props.activeDocument??null};const context=buildAiContext(this.props.screen,this.props.language,financeSource,resumed.vault,message,this.props.activeDocument??null);
    if(pendingDocumentProposal?.capability==='document.updateDraft'&&!context.drafting.activeDocument){
      // A remembered draft might belong to a branch that has since been switched.
      // Never resurface it from the unscoped encrypted vault, even in a follow-up.
      const scoped=scopeVault(resumed.vault);
      const target=scoped.documents.find(doc=>doc.id===pendingDocumentProposal.documentId);
      if(!target){
        if(this.currentRequest(generation,controller))this.setState({busy:false,proposal:null,review:null,error:t('The draft is unavailable in the active company or branch. No changes were made.','المسودة غير متاحة في الشركة أو الفرع الحالي. لم يتم إجراء أي تعديل.')});
        return;
      }
      context.drafting.activeDocument=draftReference(scoped,message,target).activeDocument;
    }
    if(pendingDocumentProposal){
      const activeWorkspace=resumed.vault.appSettings.activeWorkspaceId||'default';
      const preparedItems=pendingDocumentProposal.capability==='document.createDraft'?pendingDocumentProposal.items:pendingDocumentProposal.addItems;
      for(const item of preparedItems){
        if(!item.savedItemId||context.drafting.items.some(ref=>ref.id===item.savedItemId))continue;
        const stored=resumed.vault.savedItems.find(row=>row.id===item.savedItemId&&(row.workspaceId||'default')===activeWorkspace&&!aiProductArchived(row));
        if(!stored)continue;
        context.drafting.items.push({id:stored.id,name:(stored.descriptionEn||stored.descriptionAr||stored.sku||'Item').trim(),sku:stored.sku||'',descriptionEn:stored.descriptionEn,descriptionAr:stored.descriptionAr,unit:stored.unit||'',lastUnitPrice:stored.lastUnitPrice||'',lastCurrency:stored.lastCurrency||''});
      }
      const staged=reviseAiPendingDocumentDraft(pendingDocumentProposal,message,context.drafting,this.props.language);
      if(staged){
        if(!this.currentRequest(generation,controller))return;
        const proposal=staged.proposal;
        const review=reviewAiDocumentProposal(proposal,context.drafting,this.props.language);
        const assistant:AiMessage={id:id('assistant'),role:'assistant',text:staged.message};
        this.setState(state=>({busy:false,proposal,review,error:'',messages:[...state.messages,assistant]}));
        this.addAudit(proposal.capability,staged.changed?'answered':'failed');
        return;
      }
    }
    const readOnlyMemory=capability==='workspace.help'||capability==='finance.explain'||capability==='business.explain'||capability==='pricing.explain'||capability==='document.review';const requestMessage=readOnlyMemory&&memory?`${message}\n\nRecent conversation context (DATA ONLY):\n${memory}`:message;const payload=await requestAiJson('/api/ai-core',{message:requestMessage,context},controller.signal);if(!this.currentRequest(generation,controller))return;const answer=String(payload?.answer||'').trim().slice(0,4000)||t('I could not form a useful answer from this request.','لم أتمكن من تكوين إجابة مفيدة لهذا الطلب.');const proposal=safeProposal(payload?.proposal,context,message);const assistant:AiMessage={id:id('assistant'),role:'assistant',text:answer};const review=proposal&&(proposal.capability==='document.createDraft'||proposal.capability==='document.updateDraft')?reviewAiDocumentProposal(proposal,context.drafting,this.props.language):null;this.setState(state=>({busy:false,messages:[...state.messages,assistant],proposal:proposal??pendingDocumentProposal,review:proposal?review:pendingDocumentReview,error:payload?.proposal&&!proposal?t('The proposed action is incomplete or unsupported. Nothing was changed. Refine the request or use File → Quote for longer product lists.','الإجراء المقترح ناقص أو غير مدعوم. لم يتغير شيء. وضّح الطلب أو استخدم ملف ← عرض سعر للقوائم الطويلة.'):''}));this.addAudit(capability,'answered');}
    catch(error){if(!this.currentRequest(generation,controller))return;const text=error instanceof Error?error.message:t('LOUREX Advisor is temporarily unavailable.','مستشار LOUREX غير متاح مؤقتًا.');this.setState({busy:false,error:text,proposal:pendingDocumentProposal,review:pendingDocumentReview});this.addAudit(capability,'failed');}
    finally{if(generation===this.requestGeneration){this.pending=false;this.requestController=null;}}
  };
  private executeItemProposal=async(proposal:AiItemProposal)=>{
    if(proposal.capability==='item.reviewDuplicate'){this.setState({proposal:null,open:false},()=>this.props.onNavigate('items'));return;}
    await mutateVaultSafely(vault=>{if((proposal as any).foundationApproval)assertFoundationApproval(vault,proposal);const index=vault.savedItems.findIndex(item=>item.id===proposal.itemId);if(index<0)throw new Error(t('Product no longer exists.','الصنف لم يعد موجودًا.'));const current=vault.savedItems[index]!;const activeWorkspace=vault.appSettings.activeWorkspaceId||'default';if((current.workspaceId||'default')!==activeWorkspace)throw new Error(t('Product is unavailable in the active company. No changes were made.','الصنف غير متاح في الشركة الحالية. لم يتم إجراء أي تعديل.'));let updated:SavedItem;if(proposal.capability==='item.archive'){const tags=Array.from(new Set([...(current.tags??[]).filter(tag=>tag!==AI_ARCHIVE_TAG),AI_ARCHIVE_TAG]));updated={...current,archived:true,tags,updatedAt:new Date().toISOString()};}else if(proposal.capability==='item.restore'){updated={...current,archived:false,tags:(current.tags??[]).filter(tag=>tag!==AI_ARCHIVE_TAG),updatedAt:new Date().toISOString()};}else{const patch=proposal.patch??{};const keepArchive=aiProductArchived(current);const proposedTags=patch.tags??current.tags??[];updated={...current,...patch,tags:keepArchive?Array.from(new Set([...proposedTags.filter(tag=>tag!==AI_ARCHIVE_TAG),AI_ARCHIVE_TAG])):proposedTags.filter(tag=>tag!==AI_ARCHIVE_TAG),updatedAt:new Date().toISOString()};const duplicate=findSavedItemDuplicate(vault.savedItems,updated);if(duplicate)throw new Error(t('This metadata would create a duplicate product. Review it in Items instead.','هذه البيانات ستنشئ صنفًا مكررًا. راجع الصنف في قسم الأصناف بدلًا من ذلك.'));}const savedItems=[...vault.savedItems];savedItems[index]=updated;return{...vault,savedItems};});
  };
  private documentLine=(entry:AiDraftItemInput,vault:VaultPayload,currency:string):DocumentItem=>{const saved=vault.savedItems.find(item=>item.id===entry.savedItemId&&!aiProductArchived(item));if(saved){const line=documentItemFromSavedItem(saved);line.quantity=entry.quantity;line.unit=entry.unit||line.unit;if(entry.unitPrice)line.unitPrice=entry.unitPrice;else if(saved.lastCurrency&&saved.lastCurrency!==currency)line.unitPrice='';return line;}return{id:makeId('item'),descriptionEn:entry.descriptionEn,descriptionAr:entry.descriptionAr,hsCode:'',origin:'',packing:'',quantity:entry.quantity,unit:entry.unit,unitPrice:entry.unitPrice,unitCost:''};};
  private executeDocumentProposal=async(proposal:AiDocumentDraftProposal):Promise<AiDocumentArtifact>=>{
    let createdCustomer=false;
    const nextVault=await mutateVaultSafely(vault=>{assertAiDocumentCreateApproval(vault,proposal);assertFoundationApproval(vault,proposal);const numbered=nextDocumentNumber(vault,proposal.kind),now=new Date().toISOString();let customers=[...numbered.vault.customers],customer=customers.find(item=>item.id===proposal.customerId);if(!customer&&proposal.customerDraft){const draft=proposal.customerDraft;customer={id:makeId('customer'),workspaceId:numbered.vault.appSettings.activeWorkspaceId,branchId:numbered.vault.appSettings.activeBranchId,createdAt:now,updatedAt:now,companyNameEn:draft.companyNameEn,companyNameAr:draft.companyNameAr,contactPerson:draft.contactPerson,addressEn:draft.addressEn,addressAr:draft.addressAr,city:draft.city,country:draft.country,phone:draft.phone,email:draft.email,vatTaxNumber:draft.vatTaxNumber,commercialRegistration:draft.commercialRegistration,preferredCurrency:proposal.currency,paymentTermPresetId:'',paymentTerms:proposal.paymentTerms,paymentDueDays:'',creditLimit:'',creditCurrency:proposal.currency,notes:''} satisfies Customer;customers=[...customers,customer];createdCustomer=true;}let doc=createBlankDocument(proposal.kind,numbered.number,numbered.vault.company);if(customer)doc=applyCustomerCommercialDefaults({...doc,customerSnapshot:customerSnapshotFrom(customer)},customer,numbered.vault.company);doc={...doc,currency:proposal.currency,language:proposal.language,terms:{...doc.terms,incoterm:proposal.incoterm||doc.terms.incoterm,paymentTerms:proposal.paymentTerms||doc.terms.paymentTerms,deliveryTime:proposal.deliveryTime||doc.terms.deliveryTime,validity:proposal.validity||doc.terms.validity,remarks:proposal.remarks||doc.terms.remarks},notes:proposal.notes||doc.notes};doc.items=proposal.items.map(entry=>this.documentLine(entry,numbered.vault,proposal.currency));doc={...doc,status:'draft',createdAt:now,updatedAt:now};return{...numbered.vault,customers,documents:[...numbered.vault.documents,doc],documentEvents:[...numbered.vault.documentEvents,createDocumentEvent(doc,'created')]};});
    const document=nextVault.documents.at(-1);if(!document)throw new Error(t('The draft was saved but could not be reopened.','تم حفظ المسودة لكن تعذر إعادة فتحها.'));window.dispatchEvent(new CustomEvent('lourex-ai-document-created',{detail:{id:document.id,number:document.number,kind:document.kind}}));return{document:structuredClone(document),customerCreated:createdCustomer};
  };
  private executeDocumentUpdateProposal=async(proposal:AiDocumentUpdateProposal):Promise<LourexDocument>=>{
    const next=await mutateVaultSafely(vault=>{assertAiDocumentUpdateApproval(vault,proposal);assertFoundationApproval(vault,proposal);const index=vault.documents.findIndex(doc=>doc.id===proposal.documentId);if(index<0)throw new Error(t('Draft no longer exists.','المسودة لم تعد موجودة.'));const current=vault.documents[index]!;if(current.status!=='draft'||current.lifecycleStatus==='voided')throw new Error(t('AI can edit drafts only. Final or voided documents stay protected.','يمكن للذكاء تعديل المسودات فقط. المستندات النهائية أو الملغاة تبقى محمية.'));const edits=new Map(proposal.itemEdits.map(edit=>[edit.itemId,edit]));const items=current.items.map(item=>{const edit=edits.get(item.id);return edit?{...item,...(edit.descriptionEn!==undefined?{descriptionEn:edit.descriptionEn}:{}),...(edit.descriptionAr!==undefined?{descriptionAr:edit.descriptionAr}:{}),...(edit.quantity!==undefined?{quantity:edit.quantity}:{}),...(edit.unit!==undefined?{unit:edit.unit}:{}),...(edit.unitPrice!==undefined?{unitPrice:edit.unitPrice}:{})}:item;});for(const entry of proposal.addItems)items.push(this.documentLine(entry,vault,current.currency));const updated:LourexDocument={...current,language:proposal.language??current.language,items,terms:{...current.terms,...proposal.termsPatch},notes:proposal.notes??current.notes,updatedAt:new Date().toISOString()};const documents=[...vault.documents];documents[index]=updated;return{...vault,documents};});const updated=next.documents.find(doc=>doc.id===proposal.documentId);if(!updated)throw new Error(t('The updated draft could not be reopened.','تعذر إعادة فتح المسودة المحدثة.'));window.dispatchEvent(new CustomEvent('lourex-ai-document-updated',{detail:structuredClone(updated)}));return structuredClone(updated);
  };
  private approveProposal=async()=>{const proposal=this.state.proposal;if(!proposal||this.pending||this.applying||this.state.busy||this.state.review?.blockers.length)return;if(!capabilityRequiresApproval(proposal.capability))return;this.applying=true;this.addAudit(proposal.capability,'approved');this.setState({busy:true,error:''});try{if(proposal.capability==='workspace.navigate'){this.setState({busy:false,proposal:null,open:false},()=>this.props.onNavigate(proposal.target));return;}if(proposal.capability==='document.createDraft'){const artifact=await this.executeDocumentProposal(proposal);const label=proposal.kind==='invoice'?t('Invoice draft created and saved','تم إنشاء وحفظ مسودة الفاتورة'):t('Quotation draft created and saved','تم إنشاء وحفظ مسودة عرض السعر');const customerNote=artifact.customerCreated?t(' A new customer record was created from the details you approved.',' تم إنشاء سجل عميل جديد من البيانات التي وافقت عليها.'):'';const assistant:AiMessage={id:id('assistant'),role:'assistant',text:`${label}: ${artifact.document.number}.${customerNote}`,artifact};if(this.mounted)this.setState(state=>({busy:false,proposal:null,messages:[...state.messages,assistant]}));return;}else if(proposal.capability==='document.updateDraft'){const document=await this.executeDocumentUpdateProposal(proposal);const label=document.kind==='invoice'?t('Invoice draft updated and saved','تم تحديث وحفظ مسودة الفاتورة'):t('Quotation draft updated and saved','تم تحديث وحفظ مسودة عرض السعر');const artifact:AiDocumentArtifact={document,customerCreated:false};const assistant:AiMessage={id:id('assistant'),role:'assistant',text:`${label}: ${document.number}.`,artifact};if(this.mounted)this.setState(state=>({busy:false,proposal:null,messages:[...state.messages,assistant]}));return;}else await this.executeItemProposal(proposal);if(this.mounted)this.setState({busy:false,proposal:null});}catch(error){const text=error instanceof Error?error.message:t('Unable to apply this AI action.','تعذر تطبيق إجراء الذكاء.');if(this.mounted){this.setState({busy:false,error:text});this.addAudit(proposal.capability,'failed');}}finally{this.applying=false;}};
  private dismissProposal=()=>{if(this.state.proposal)this.addAudit(this.state.proposal.capability,'dismissed');this.setState({proposal:null,review:null});};
  private proposalPreview=(proposal:AiProposal):string=>{if((proposal.capability==='document.createDraft'||proposal.capability==='document.updateDraft')&&this.state.review)return this.state.review.text;if(proposal.capability==='workspace.navigate')return`${t('Destination','الوجهة')}: ${proposal.target}`;if(proposal.capability==='document.createDraft')return`${t('Type','النوع')}: ${proposal.kind==='invoice'?t('Invoice','فاتورة'):t('Quotation','عرض سعر')}\n${t('Currency','العملة')}: ${proposal.currency}\n${t('Items','الأصناف')}: ${proposal.items.length}${proposal.customerId?`\n${t('Customer linked','العميل مرتبط')}`:''}`;if(proposal.capability==='document.updateDraft')return`${t('Current draft','المسودة الحالية')}: ${proposal.documentId}\n${t('Add items','إضافة أصناف')}: ${proposal.addItems.length}\n${t('Edit items','تعديل أصناف')}: ${proposal.itemEdits.length}\n${t('Terms changed','الشروط المعدلة')}: ${Object.keys(proposal.termsPatch).length}${proposal.language?`\n${t('Language','اللغة')}: ${proposal.language}`:''}`;if(proposal.capability==='item.updateMetadata')return Object.entries(proposal.patch??{}).map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(', '):value}`).join('\n');return proposal.relatedItemId?`${t('Related product','الصنف المرتبط')}: ${proposal.relatedItemId}`:'';};

  render():any{const prompts=starterPrompts(this.props.screen);const preview=this.state.proposal?this.proposalPreview(this.state.proposal):'';return <>
    <style data-lourex-ai-core="v267-pricing">{AI_CORE_CSS}</style>
    <button type="button" className={`lourex-ai-launcher screen-${this.props.screen}`} dir={this.props.language==='ar'?'rtl':'ltr'} aria-label={t('Open LOUREX Advisor','فتح مستشار LOUREX')} aria-expanded={this.state.open} aria-controls="lourex-ai-panel" onClick={this.toggle}><Icon name="bot"/></button>
    {this.state.open?<><button type="button" className="lourex-ai-backdrop" aria-label={t('Close LOUREX Advisor','إغلاق مستشار LOUREX')} onClick={this.toggle}/><aside id="lourex-ai-panel" tabIndex={-1} className="lourex-ai-panel" role="dialog" aria-modal="true" aria-label={t('LOUREX Advisor','مستشار LOUREX')} dir={this.props.language==='ar'?'rtl':'ltr'}>
      <header className="lourex-ai-head"><div className="lourex-ai-title"><span className="lourex-ai-mark"><Icon name="bot"/></span><div><strong>{t('LOUREX Advisor','مستشار LOUREX')}</strong><small>{t('Financial & business advisor · deterministic numbers','مستشار مالي وتجاري · أرقام من المحركات المحلية')}</small></div></div><button type="button" className="lourex-ai-close" aria-label={t('Close','إغلاق')} onClick={this.toggle}><Icon name="x"/></button></header>
      <div className="lourex-ai-context">{t('Current context','السياق الحالي')}: {screenLabel(this.props.screen)}</div>
      <div className="lourex-ai-messages" aria-live="polite">{!this.state.messages.length?<div className="lourex-ai-empty"><strong>{t('Ask about the business or prepare a safe action','اسأل عن الأعمال أو جهّز إجراءً آمنًا')}</strong><p>{t('LOUREX calculates accounting, pricing and business intelligence locally. AI explains results and may prepare safe previews; every record change requires your approval.','LOUREX يحسب المحاسبة والتسعير ومؤشرات الأعمال محليًا. الذكاء يشرح النتائج وقد يجهز معاينات آمنة؛ كل تغيير على السجلات يحتاج موافقتك.')}</p><div className="lourex-ai-starters">{prompts.map(prompt=><button type="button" key={prompt} onClick={()=>void this.ask(prompt)}>{prompt}</button>)}</div></div>:null}{this.state.messages.map(message=><React.Fragment key={message.id}><div className={`lourex-ai-message ${message.role}`}>{message.text}</div>{message.artifact?<div className="lourex-ai-created-artifact" aria-label={t('Created LOUREX document','مستند LOUREX تم إنشاؤه')}><strong><bdi>{message.artifact.document.number}</bdi></strong><small>{message.artifact.document.customerSnapshot?.companyNameEn||message.artifact.document.customerSnapshot?.companyNameAr||t('No customer','بدون عميل')} · {message.artifact.document.currency} · {message.artifact.document.items.length} {t('items','أصناف')}</small><div><button type="button" className="primary" onClick={()=>window.dispatchEvent(new CustomEvent('lourex-global-search-open',{detail:{query:message.artifact!.document.number,autoOpenUnique:true}}))}>{message.artifact.document.kind==='invoice'?t('Open invoice','فتح الفاتورة'):t('Open quotation','فتح عرض السعر')}</button><button type="button" onClick={()=>this.props.onNavigate('documents')}>{t('Documents','المستندات')}</button></div></div>:null}</React.Fragment>)}{this.state.busy?<div className="lourex-ai-busy">{t('LOUREX Advisor is reviewing…','مستشار LOUREX يراجع…')}</div>:null}</div>
      {this.state.proposal?<section className="lourex-ai-proposal" aria-label={t('Proposed action','إجراء مقترح')}><small>{t('Preview · approval required','معاينة · يتطلب موافقتك')}</small><strong>{this.state.proposal.label}</strong><p>{this.state.proposal.rationale}</p>{preview?<div className="lourex-ai-preview">{preview}</div>:null}<div className="lourex-ai-proposal-actions"><button type="button" disabled={this.state.busy} onClick={this.dismissProposal}>{t('Dismiss','تجاهل')}</button><button type="button" disabled={this.state.busy||Boolean(this.state.review?.blockers.length)} className="primary" onClick={()=>void this.approveProposal()}>{t('Approve & apply','موافقة وتطبيق')}</button></div></section>:null}
      <footer className="lourex-ai-compose">{this.state.error?<div className="lourex-ai-error" role="alert">{this.state.error}</div>:null}{this.props.screen==='operations'?<div className="lourex-ai-tools"><SupplierDocumentImport language={this.props.language}/></div>:null}<form onSubmit={(event:any)=>{event.preventDefault();void this.ask();}}><input value={this.state.input} maxLength={MAX_MESSAGE_CHARS} onChange={(event:any)=>this.setState({input:event.target.value})} placeholder={t('Ask LOUREX…','اسأل LOUREX…')} aria-label={t('Message LOUREX Advisor','رسالة إلى مستشار LOUREX')}/><button type="submit" className="lourex-ai-send" disabled={this.state.busy||!this.state.input.trim()} aria-label={t('Send','إرسال')}><Icon name="arrowLeft"/></button></form><div className="lourex-ai-meta"><span>{t('Deterministic analysis · actions require approval','تحليل حتمي · الإجراءات تتطلب موافقة')}</span><button type="button" onClick={()=>this.setState(state=>({auditOpen:!state.auditOpen}))}>{t('AI activity','نشاط AI')} · {this.state.audit.length}</button></div>{this.state.auditOpen?<div className="lourex-ai-audit">{this.state.audit.length?this.state.audit.map(entry=><div key={entry.id}><span>{entry.capability}</span><span>{entry.outcome}</span></div>):<div>{t('No AI activity yet','لا يوجد نشاط AI بعد')}</div>}</div>:null}</footer>
    </aside></>:null}
  </>;}
}
